import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"外存算法与 I/O 模型","description":"","frontmatter":{"title":"外存算法与 I/O 模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/external-memory-model.md","filePath":"cs/external-memory-model.md","lastUpdated":1789023840000}'),c={name:"cs/external-memory-model.md"};function m(_,a,u,B,f,A){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="外存算法与-i-o-模型" tabindex="-1">外存算法与 I/O 模型 <a class="header-anchor" href="#外存算法与-i-o-模型" aria-label="Permalink to &quot;外存算法与 I/O 模型&quot;">​</a></h1><div class="epigraph"><p>内存 $M$、块 $B$，代价是块传输次数；排序 $\\Theta(\\frac{N}{B}\\log_{M/B}\\frac{N}{B})$ 次 I/O，不是 RAM 的 $n\\log n$ 比较。</p><footer>—— 据 Aggarwal and Vitter, The Input/Output Complexity of Sorting and Related Problems, 1988；Vitter 外存算法综述整理</footer></div><p>上一课<a href="/cs/misra-gries">Misra–Gries</a>假定流过 CPU。数据在盘上：随机访问一次块与扫一块同量级贵。缺口是 I/O 模型：扫描 \\(O(N/B)\\)，排序多路归并。不重写 RAM 快排。后课 PRAM 是并行，不是盘。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>参数 \\(N,M,B\\)，常 \\(M\\gg B\\)。扫描顺序文件最优。排序：\\(\\Theta(M/B)\\) 路归并，I/O 如题记。B 树、外存优先队列、缓存无关模型（<a href="/cs/cache-oblivious">cache-oblivious</a> 若已写则引用）点名。图外存更难（边定向）。</p><p>缺口是计数 I/O，不是 CPU 比较下界（后课对手）。</p><h3 id="不是「内存不够就虚拟内存」" tabindex="-1">不是「内存不够就虚拟内存」 <a class="header-anchor" href="#不是「内存不够就虚拟内存」" aria-label="Permalink to &quot;不是「内存不够就虚拟内存」&quot;">​</a></h3><p>OS 分页是 LRU 在线；算法应显式扫块。虚拟内存可能抖动。外存算法自己安排传输。</p><p><span class="marginnote">Aggarwal–Vitter 1988。Vitter 综述。后课 PRAM 前缀和。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>顺序扫描、多路归并、分块矩阵乘（块 \\(B^{1/2}\\)）。图：扫描边列表多次，避免随机点。</p>',11)),(e(),n(p,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISK%5B%22N%20%E6%9D%A1%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20BLK%5B%22%E5%9D%97%20B%22%5D%0A%20%20BLK%20--%3E%20SORT%5B%22%E5%A4%9A%E8%B7%AF%E5%BD%92%E5%B9%B6%20I%2FO%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>缓存无关：不把 \\(B\\) 写入代码，用递归分治。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>传输一次 \\(B\\) 个元素均摊。比较在内存免费（相对 I/O）。与流：流 \\(B=1\\) 或单次扫描；外存可多遍但要少遍。与 CH：路网可外存预处理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写并行盘阵列全文。不写具体文件系统。后课默认：大数据排序用 I/O 公式。下一课 PRAM 与前缀和。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代价是块 I/O；\\(M,B\\) 是参数。</li><li>外存排序多路归并。</li><li>随机访问按块计，极贵。</li><li>出处：Aggarwal and Vitter, 1988。</li></ul>',7))])}const b=l(c,[["render",m]]);export{T as __pageData,b as default};
